function pobierzParametrZle(nazwa) {
  const czesci = location.search.slice(1).split("&"); // ZLE - kruche recznie
  for (const czesc of czesci) {
    const [klucz, wartosc] = czesc.split("=");
    if (klucz === nazwa) return wartosc; // BEZ dekodowania %20, + itd.
  }
  return null;
}

function pobierzParametrDobrze(nazwa) {
  const params = new URLSearchParams(location.search); // DOBRZE
  return params.get(nazwa);
}

