// location.href = '/strona' DODAJE nowy wpis do historii nawigacji -
// przycisk 'Wstecz' wroci do AKTUALNEJ strony (tej, z ktorej nastapilo
// przekierowanie).
// location.replace('/strona') ZASTEPUJE aktualny wpis w historii -
// przycisk 'Wstecz' POMINIE aktualna strone, jakby jej wcale nie bylo
// (typowe zastosowanie: przekierowanie po zalogowaniu, zeby 'Wstecz'
// nie wracalo do strony logowania).

function sprawdzProtokol() {
  if (location.protocol !== "https:") {
    console.log("Polaczenie niezabezpieczone");
  }
}

sprawdzProtokol();

// Reczne dzielenie location.search przez split('&')/split('=') jest
// krucha metoda - nie dekoduje automatycznie zakodowanych znakow
// specjalnych (np. spacje zapisane jako %20 lub +, polskie znaki jako
// %C4%85 itd.) i latwo popelnic blad przy parametrach bez wartosci
// (np. '?debug') lub z wieloma znakami '=' w wartosci. URLSearchParams
// to wbudowany, w pelni przetestowany parser, ktory poprawnie
// obsluguje wszystkie te przypadki brzegowe za jednym wywolaniem.

const location = {
  href: "https://example.com:8080/products?category=js&page=2#reviews",
  protocol: "https:",
  host: "example.com:8080",
  hostname: "example.com",
  port: "8080",
  pathname: "/products",
  search: "?category=js&page=2",
  hash: "#reviews",
