function zbudujUrlZListaParametrow(baza, parametry) {
  const url = new URL(baza);
  for (const [klucz, wartosc] of parametry) {
    url.searchParams.set(klucz, wartosc);
  }
  return url.toString();
}
console.log(zbudujUrlZListaParametrow("https://api.example.com/szukaj", [
  ["q", "javascript"],
  ["limit", "10"],
  ["strona", "1"],
]));
// "https://api.example.com/szukaj?q=javascript&limit=10&strona=1"

function parametryDoObiektu(search) {
  const params = new URLSearchParams(search);
  return Object.fromEntries(params.entries());
}
console.log(parametryDoObiektu("?jezyk=pl&motyw=ciemny"));
// { jezyk: "pl", motyw: "ciemny" }

function usunParametr(search, nazwa) {
  const params = new URLSearchParams(search);
  params.delete(nazwa);
  return params.toString();
}
console.log(usunParametr("?kategoria=js&cena=100", "cena"));
// "kategoria=js"

function zmienStroneWQuery(search, nowaStrona) {
  const params = new URLSearchParams(search);
  params.set("strona", String(nowaStrona));
  return params.toString();
}
console.log(zmienStroneWQuery("?kategoria=js&strona=1", 2));
// "kategoria=js&strona=2"

function mergujParametry(bazowySearch, noweParametry) {
  const params = new URLSearchParams(bazowySearch);
  for (const [klucz, wartosc] of Object.entries(noweParametry)) {
    params.set(klucz, wartosc);
  }
  return params.toString();
}
console.log(mergujParametry("?kategoria=js", { cena: "100", sortuj: "cena" }));
// "kategoria=js&cena=100&sortuj=cena"

const location = {
  _historia: ["/logowanie"],
  assign(url) { this._historia.push(url); },
  replace(url) { this._historia[this._historia.length - 1] = url; },
};
function przekierujPoLogowaniu(location) {
  location.replace("/panel");
}
przekierujPoLogowaniu(location);
console.log(location._historia);
// ["/panel"] - "/logowanie" zostalo ZASTAPIONE, nie dodano nowego wpisu

function sprawdzCzyMaWszystkieParametry(search, wymagane) {
  const params = new URLSearchParams(search);
  return wymagane.every((nazwa) => params.has(nazwa));
}
console.log(sprawdzCzyMaWszystkieParametry("?a=1&b=2&c=3", ["a", "b"]));
console.log(sprawdzCzyMaWszystkieParametry("?a=1", ["a", "b"]));
// true
// false

function policzParametry(search) {
  const params = new URLSearchParams(search);
  return [...params].length;
}
console.log(policzParametry("?a=1&b=2&a=3"));
// 3 - wliczajac duplikat "a"

function zbudujUrlWzgledny(baza, sciezka) {
  return new URL(sciezka, baza).href;
}
console.log(zbudujUrlWzgledny("https://example.com/katalog/", "../inny"));
console.log(zbudujUrlWzgledny("https://example.com/katalog/", "./podstrona"));
// "https://example.com/inny"
// "https://example.com/katalog/podstrona"

function pobierzWszystkieParametry(search) {
  return [...new URLSearchParams(search)];
}
console.log(pobierzWszystkieParametry("?tag=js&tag=web"));
// [["tag", "js"], ["tag", "web"]] - oba wpisy zachowane osobno

function zbudujLinkDoUdostepnienia(bazowyUrl, filtry) {
  const url = new URL(bazowyUrl);
  for (const [klucz, wartosc] of Object.entries(filtry)) {
    if (wartosc !== "") url.searchParams.set(klucz, wartosc);
  }
  return url.toString();
}
console.log(zbudujLinkDoUdostepnienia("https://sklep.pl/produkty", { kategoria: "buty", kolor: "" }));
// "https://sklep.pl/produkty?kategoria=buty" - pusty "kolor" pominiety

function jestBezpiecznyProtokol(location) {
  return location.protocol === "https:" || location.protocol === "http:";
}
console.log(jestBezpiecznyProtokol({ protocol: "https:" }));
console.log(jestBezpiecznyProtokol({ protocol: "file:" }));
// true
// false

function wyciagnijIdZUrl(pathname) {
  const segmenty = pathname.split("/").filter(Boolean);
  return segmenty[segmenty.length - 1];
}
console.log(wyciagnijIdZUrl("/produkty/42"));
console.log(wyciagnijIdZUrl("/uzytkownicy/anna/profil"));
// "42"
// "profil"

// Fragment adresu URL (wszystko po znaku #, dostepne jako
// location.hash) to mechanizm dzialajacy WYLACZNIE po stronie
// przegladarki - z definicji protokolu HTTP, przegladarka NIGDY nie
// wysyla tej czesci adresu do serwera przy zadaniu. Historycznie hash
// sluzyl do "kotwic" (przewijania do konkretnego miejsca na stronie),
// a wspolczesnie jest tez wykorzystywany np. przez routery
// jednostronicowych aplikacji (SPA) do symulowania nawigacji bez
// przeladowania strony. location.search (parametry zapytania) NATOMIAST
// jest w pelni wysylane do serwera jako czesc adresu zadania.
console.log("hash nigdy nie trafia do serwera, search - tak");

